      if let enumResultAsInt = enumResultAsInt {
        return NotificationPermission(rawValue: enumResultAsInt)
      }
      return nil
    case 134:
      let enumResultAsInt: Int? = nilOrValue(self.readValue() as! Int?)
      if let enumResultAsInt = enumResultAsInt {
        return KernelVerdict(rawValue: enumResultAsInt)
      }
      return nil
    case 135:
