      if let enumResultAsInt = enumResultAsInt {
        return ShellEventType(rawValue: enumResultAsInt)
      }
      return nil
    case 136:
      return ShellConfigDto.fromList(self.readValue() as! [Any?])
    case 137:
      return ShellInfo.fromList(self.readValue() as! [Any?])
    case 138:
      return WebEvent.fromList(self.readValue() as! [Any?])
    case 139:
      return OpenChatRequest.fromList(self.readValue() as! [Any?])
    case 140:
      return PushMessage.fromList(self.readValue() as! [Any?])
    case 141:
