    } else if let value = value as? ShellConfigDto {
      super.writeByte(136)
      super.writeValue(value.toList())
    } else if let value = value as? ShellInfo {
      super.writeByte(137)
      super.writeValue(value.toList())
    } else if let value = value as? WebEvent {
      super.writeByte(138)
      super.writeValue(value.toList())
    } else if let value = value as? OpenChatRequest {
      super.writeByte(139)
      super.writeValue(value.toList())
    } else if let value = value as? PushMessage {
      super.writeByte(140)
      super.writeValue(value.toList())
    } else if let value = value as? PushDecision {
      super.writeByte(141)
      super.writeValue(value.toList())
    } else if let value = value as? KernelInfo {
      super.writeByte(142)
      super.writeValue(value.toList())
    } else if let value = value as? ConsoleRecord {
      super.writeByte(143)
      super.writeValue(value.toList())
    } else if let value = value as? ShellDiagnostics {
      super.writeByte(144)
      super.writeValue(value.toList())
    } else if let value = value as? ShellEvent {
      super.writeByte(145)
      super.writeValue(value.toList())
    } else {
